-- ============================================================================
-- 0028 · Nombres de zona corregidos: tildes, El Salvador y Paraguay con la fuente oficial
-- ============================================================================
-- Revisión de los nombres cargados en 0020 y 0025 a 0027 (regenerados con `npm run zonas`):
--
--   · Tildes. Costa Rica, Ecuador, Honduras y los distritos de Perú vienen de fuentes sin tildes
--     ("San Jose", "Concepcion de Maria"). Se corrigen solo palabras que en español se escriben siempre
--     igual (scripts/tildes-zonas.mjs): "San José", "Concepción de María", "San Martín de Porres".
--   · El Salvador: la edición abierta traía diez zonas llamadas "Null", nombres con errores
--     ("Ahuachpan", "Chalatenago") y cuatro lagos. Ahora la edición humanitaria (www.gadm.org, HDX, CC BY 3.0
--     IGO): 262 distritos (los antiguos municipios, que desde 2024 forman 44 municipios nuevos).
--   · Paraguay: la edición abierta abreviaba y cortaba nombres ("San Juan Delparana", "Tte 1Ro…").
--     Ahora la edición humanitaria (DGEEC, HDX, CC BY 3.0 IGO): 250 distritos con su nombre oficial.
--   · Lagos que la fuente dibujaba como zona (Yojoa, Atitlán, Amatitlán), "Isle of Youth" (Isla de la
--     Juventud), "Municipality A" (Municipio A de Montevideo), "Bogotá, D.c." y espacios dobles.
--
--   CL: 1 con el nombre corregido
--   PE: 104 con el nombre corregido, 14 provincias con tilde
--   AR: 2 con el nombre corregido
--   BO: 2 con el nombre corregido
--   CO: 19 con el nombre corregido
--   CR: 14 con el nombre corregido
--   CU: 1 salen, 1 entran con código nuevo
--   DO: 5 con el nombre corregido
--   EC: 9 con el nombre corregido
--   SV: 272 → 262 zonas, desde la fuente nueva
--   GT: 2 salen
--   HN: 43 con el nombre corregido, 1 salen
--   MX: 2 con el nombre corregido
--   NI: 2 con el nombre corregido
--   PY: 247 → 250 zonas, desde la fuente nueva
--   UY: 1 con el nombre corregido, 8 salen, 8 entran con código nuevo
--   VE: 1 con el nombre corregido
--
-- Las zonas que ya copió un CRM (territories) reciben el nombre corregido, salvo que alguien lo haya
-- cambiado. Las que salen del catálogo no pueden estar en uso: si algún CRM ya las tiene, la
-- migración se detiene sin cambiar nada.
-- ============================================================================

DO $$
DECLARE
    v_en_uso TEXT;
BEGIN
    SELECT string_agg(DISTINCT t.country_code || ' ' || t.code, ', ') INTO v_en_uso
    FROM public.territories t
    WHERE t.country_code IN ('SV', 'PY')
       OR (t.country_code, t.code) IN (VALUES
    ('CU', 'CU-99-ISLE-OF-YOUTH'),
    ('GT', 'GT-GU-LAGO-DE-AMATITLAN'),
    ('GT', 'GT-SO-LAGO-DE-ATITLAN'),
    ('HN', 'HN-CR-LAGO-DE-YOJOA'),
    ('UY', 'UY-MO-MUNICIPALITY-A'),
    ('UY', 'UY-MO-MUNICIPALITY-B'),
    ('UY', 'UY-MO-MUNICIPALITY-C'),
    ('UY', 'UY-MO-MUNICIPALITY-CH'),
    ('UY', 'UY-MO-MUNICIPALITY-D'),
    ('UY', 'UY-MO-MUNICIPALITY-E'),
    ('UY', 'UY-MO-MUNICIPALITY-F'),
    ('UY', 'UY-MO-MUNICIPALITY-G')
       );
    IF v_en_uso IS NOT NULL THEN
        RAISE EXCEPTION 'Hay CRMs que ya usan zonas que esta migración reemplaza: %', v_en_uso;
    END IF;
END
$$;

-- ------------------------------------------------------------------ zonas que salen del catálogo
DELETE FROM public.zone_catalog
WHERE country_code IN ('SV', 'PY')
   OR (country_code, code) IN (VALUES
    ('CU', 'CU-99-ISLE-OF-YOUTH'),
    ('GT', 'GT-GU-LAGO-DE-AMATITLAN'),
    ('GT', 'GT-SO-LAGO-DE-ATITLAN'),
    ('HN', 'HN-CR-LAGO-DE-YOJOA'),
    ('UY', 'UY-MO-MUNICIPALITY-A'),
    ('UY', 'UY-MO-MUNICIPALITY-B'),
    ('UY', 'UY-MO-MUNICIPALITY-C'),
    ('UY', 'UY-MO-MUNICIPALITY-CH'),
    ('UY', 'UY-MO-MUNICIPALITY-D'),
    ('UY', 'UY-MO-MUNICIPALITY-E'),
    ('UY', 'UY-MO-MUNICIPALITY-F'),
    ('UY', 'UY-MO-MUNICIPALITY-G')
   );

